CREATE TABLE institutional_flow_editions(id uuid PRIMARY KEY,actor_id text NOT NULL,fingerprint text NOT NULL,source_hash text NOT NULL,input jsonb NOT NULL,receipt jsonb,error text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((receipt IS NULL)=(error IS NOT NULL)));
CREATE TABLE institutional_flow_reviews(seq bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,request_id uuid UNIQUE NOT NULL,edition_id uuid NOT NULL REFERENCES institutional_flow_editions(id),actor_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX institutional_flow_date ON institutional_flow_editions((receipt->>'source'));
CREATE TRIGGER institutional_flow_editions_immutable BEFORE UPDATE OR DELETE ON institutional_flow_editions FOR EACH ROW EXECUTE FUNCTION protect_reviewed_event_history();
CREATE TRIGGER institutional_flow_reviews_immutable BEFORE UPDATE OR DELETE ON institutional_flow_reviews FOR EACH ROW EXECUTE FUNCTION protect_reviewed_event_history();
